// Normalize incoming payload from the React "Ask Swarnix" widget.
// Expected body: { owner_id, asked_by, question }
const body = $input.first().json.body || $input.first().json;
const question = String(body.question || '').trim();

if (!question) {
  throw new Error('Missing "question" in request body');
}

return [{
  json: {
    ownerId: body.owner_id || '',
    askedBy: body.asked_by || 'owner',
    question
  }
}];

// Extract the 768-dim embedding vector from Gemini's response.
const resp = $input.first().json;
const values = resp.embedding && resp.embedding.values;

if (!Array.isArray(values) || values.length === 0) {
  throw new Error('Gemini embedding response missing embedding.values');
}

return [{
  json: {
    ownerId:   $('Parse Request').first().json.ownerId,
    askedBy:   $('Parse Request').first().json.askedBy,
    question:  $('Parse Request').first().json.question,
    embedding: values
  }
}];

// Build the grounding context block for the AI Agent from the matched SOP
// chunks. If nothing matches well (similarity too low), flag it so the agent
// can honestly say it doesn't know rather than hallucinate.
const matches = $input.first().json || [];
const rows = Array.isArray(matches) ? matches : [];

const SIMILARITY_FLOOR = 0.55; // below this, treat as "no good match"
const goodRows = rows.filter(r => (r.similarity || 0) >= SIMILARITY_FLOOR);

let context = '';
if (goodRows.length === 0) {
  context = 'NO_MATCHING_SOP_FOUND: None of the SOP documents are a confident match for this question.';
} else {
  context = goodRows.map((r, i) =>
    `--- SOP ${i + 1}: ${r.title} ---\n${r.content}`
  ).join('\n\n');
}

return [{
  json: {
    ownerId:      $('Parse Request').first().json.ownerId,
    askedBy:      $('Parse Request').first().json.askedBy,
    question:     $('Parse Request').first().json.question,
    matchedSlugs: goodRows.map(r => r.slug),
    sopContext:   context,
    hasMatch:     goodRows.length > 0
  }
}];

// Log the Q&A for analytics/debugging (non-fatal if it fails) and shape the
// final response payload for the React widget.
const agentOut = $input.first().json;
const ctx = $('Build SOP Context').first().json;
const answer = String(agentOut.output || '').trim();

try {
  const SK = $env.SUPABASE_SERVICE_KEY || '';
  await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://bigmdvjrvqyqzyrijdum.supabase.co/rest/v1/sop_chat_logs',
    headers: {
      apikey: SK,
      Authorization: 'Bearer ' + SK,
      'Content-Type': 'application/json',
      Prefer: 'return=minimal'
    },
    body: {
      owner_id: ctx.ownerId || null,
      asked_by: ctx.askedBy || 'owner',
      question: ctx.question,
      matched_slugs: ctx.matchedSlugs || [],
      answer
    },
    json: true
  });
} catch (e) { /* non-fatal — the chat reply must still go out */ }

return [{
  json: {
    answer,
    matchedSlugs: ctx.matchedSlugs || [],
    hasMatch: ctx.hasMatch
  }
}];
